def amount(resource, quality):
    """Piece.Requirement.GetAmount: how many of an ingredient one craft (quality 1) or one upgrade to `quality` takes."""
    _, base, per_level, idol, _ = resource
    if quality <= 1:
        return base
    steps = 4.0 + (quality - 4) / 2.0 if quality >= 4 else float(quality - 1)
    return math.floor(steps * per_level + (base if idol else 0))


def refund(resource, quality):
    """What a break returns of one ingredient, when the item broke going to `quality` (InventoryGui.DoCrafting)."""
    if not resource[4]:
        return 0
    total = oracle.f32(oracle.f32(amount(resource, 1) + amount(resource, quality - 1)) * oracle.f32(BREAK_RETURN))
    return math.ceil(total)


def find(text):
    """A prefab name from a prefab name or a display name (case does not matter)."""
    low = text.lower()
    for prefab, info in ITEMS.items():
        if low in (prefab.lower(), info["name"].lower()):
            return prefab
    matches = [p for p, info in ITEMS.items() if low in info["name"].lower() or low in p.lower()]
    if len(matches) == 1:
        return matches[0]
    raise oracle.SaveError(f"{text!r} is not an item the Forge of Potential can upgrade" if not matches else
                           f"{text!r} matches several items: " + ", ".join(sorted(ITEMS[m]["name"] for m in matches)[:12]))


def simulate(prefab, target, name, seeds, max_copies=MAX_COPIES):
    """Craft copies of the item and upgrade them, as one character, until one reaches `target`.

    Returns the copies (how far each got), and Counters of what was spent and refunded."""
    info = ITEMS[prefab]
    station = [r for r in info["resources"] if not r[3]]
    idols = [r for r in info["resources"] if r[3]]
    cap = info["cap"]
    seeds = dict(seeds)                         # the replay moves the character's seeds on as the game would
    base, name_hash = oracle.stable_hash(prefab), oracle.stable_hash(name)
    spent, refunded, copies = Counter(), Counter(), []
    while len(copies) < max_copies:
        for ingredient, count, _ in info["craft"]:  # craft a new copy (cast and fuel, gear ingredients expanded)...
            spent[ingredient] += count
        for q in range(2, min(cap, target) + 1):    # ...and upgrade it at its station
            for r in station:
                if amount(r, q):
                    spent[r[0]] += amount(r, q)
        level, steps = min(cap, target), []
        while level < target:                   # then the Forge of Potential
            to = level + 1
            for r in idols:
                spent[r[0]] += amount(r, to)
            key = oracle.s32(base + to)
            saved = key in seeds
            value, seeds[key] = oracle.roll(seeds[key] if saved else oracle.s32(name_hash + key))
            if oracle.UPGRADE_CHANCE >= value:
                steps.append((to, value, True, saved))
                level = to
                continue
            if oracle.BREAK_CHANCE < oracle.f32(1.0 - value):
                raise oracle.SaveError("this item can lose a level instead of breaking, which this tool does not model")
            steps.append((to, value, False, saved))
            for r in info["resources"]:
                if refund(r, to):
                    refunded[r[0]] += refund(r, to)
            break
        copies.append({"reached": level, "steps": steps})
        if level >= target:
            return copies, spent, refunded, True
    return copies, spent, refunded, False


def gear_parts(info):
    """{gear ingredient: [(ingredient, amount)]} for the gear a new copy is made from (the Nord Sword in a Frostfire Sword)."""
    parts = {}
    for n, a, gear in info["craft"]:
        if gear:
            parts.setdefault(gear, []).append((n, a))
    return parts


def report(prefab, target, name, source, copies, spent, refunded, done, verbose):
    info = ITEMS[prefab]
    cap = info["cap"]
    print(f"{info['name']} to quality {target}, upgraded by {name!r} ({source})")
    where = info["station"] or "no station"
    note = (f", which is as far as {where} goes (it reaches level {info['stationMaxLevel']})"
            if cap < info["maxQuality"] else "")
    via = info["via"]
    made = (f"Crafted as {via['cast']} at {where}, then cooked in the {via['foundry']} with {via['perCast']} "
            f"{via['fuel']} per cast" if via else f"Crafted at {where}")
    print(f"  {made}; each copy is upgraded at {where} to quality {min(cap, target)}{note}.")
    for gear, parts in gear_parts(info).items():
        print(f"  Each copy also takes a new {gear}, counted as what it takes to craft: "
              + ", ".join(f"{a:g} {n}" for n, a in parts) + ".")
    if info["notRefunded"]:
        print(f"  Its upgrade recipe leaves out the {', '.join(info['notRefunded'])} that the craft takes, so a break never "
              "refunds it. That looks like a game bug.")
    print(f"  Never refunded on a break: {', '.join(info['neverRefunded'])}.")
    if info["season"]:
        print(f"  Its recipe is seasonal: only available during {info['season']}.")
    if target > cap:
        attempts = sum(len(c["steps"]) for c in copies)
        print(f"  Forge of Potential: {attempts} attempt{'s' if attempts != 1 else ''}, "
              f"{len(copies) - (1 if done else 0)} break{'s' if len(copies) - (1 if done else 0) != 1 else ''}, "
              f"{len(copies)} cop{'y' if len(copies) == 1 else 'ies'} crafted.")
    if not done:
        print(f"  Not reached: still breaking after {len(copies):,} copies. The totals below are for those copies.")
    if verbose and target > cap:
        for i, c in enumerate(copies, 1):
            path = " ".join(f"{to}{'✓' if ok else '✗'}" for to, _, ok, _ in c["steps"])
            print(f"    copy {i}: {min(cap, target)} → {path}")
    print()
    width = max(len(k) for k in spent) if spent else 10
    print(f"  {'Ingredient':<{width}}  {'spent':>9}  {'refunded':>9}  {'net':>9}")
    for k in sorted(spent, key=lambda k: (k not in {r[0] for r in info['resources'] if r[3]}, k)):
        print(f"  {k:<{width}}  {spent[k]:>9,}  {refunded[k]:>9,}  {spent[k] - refunded[k]:>9,}")


