def web_cost_items():
    """JSON list of the display names of every item the Forge of Potential can upgrade."""
    return json.dumps(sorted((v["name"] for v in ITEMS.values()), key=str.lower))


def web_cost(item, target, name, data=None):
    """JSON for the page's cost tool. `data` is a character file's bytes (then its name and seeds are used)."""
    try:
        target = int(target)
        if not 1 <= target <= oracle.WEB_MAX_QUALITY:
            raise oracle.SaveError(f"the target quality must be between 1 and {oracle.WEB_MAX_QUALITY}")
        prefab = find(item)
        if data is not None and type(data).__name__ != "JsNull":
            save = oracle.load(bytes(data.to_py()) if hasattr(data, "to_py") else bytes(data))
            name, seeds, source = save["name"], save["seeds"], "file"
        elif not name:
            raise oracle.SaveError("enter a character name or choose a character file")
        else:
            seeds, source = {}, "name"
        copies, spent, refunded, done = simulate(prefab, target, name, seeds, WEB_MAX_COPIES)
    except oracle.SaveError as e:
        return json.dumps({"error": str(e)})
    info = ITEMS[prefab]
    idols = {r[0] for r in info["resources"] if r[3]}
    rows = [{"name": k, "spent": spent[k], "refunded": refunded[k], "net": spent[k] - refunded[k], "idol": k in idols}
            for k in sorted(spent, key=lambda k: (k not in idols, k))]
    # every copy's Forge attempts as a compact string, "1" a success and "0" the break: "110" went up twice, then broke
    listed = ["".join("1" if ok else "0" for _, _, ok, _ in c["steps"]) for c in copies]
    return json.dumps({"item": info["name"], "target": target, "character": name, "source": source,
                       "savedSeeds": len(seeds), "station": info["station"], "cap": info["cap"],
                       "maxQuality": info["maxQuality"], "stationMaxLevel": info["stationMaxLevel"],
                       "season": info["season"], "via": info["via"], "notRefunded": info["notRefunded"],
                       "gear": [{"name": g, "parts": [{"name": n, "amount": a} for n, a in p]}
                                for g, p in gear_parts(info).items()],
                       "neverRefunded": info["neverRefunded"],
                       "reached": done, "copies": len(copies),
                       "attempts": sum(len(c["steps"]) for c in copies), "rows": rows, "list": listed,
                       "maxCopies": WEB_MAX_COPIES})


def main():
    ap = argparse.ArgumentParser(description="What one character pays to get an item to a quality at the Forge of "
                                 "Potential, crafting a new copy after every break.")
    ap.add_argument("--item", required=True, help="the item, by display name or prefab name (e.g. 'Iron Sword')")
    ap.add_argument("--target", required=True, type=int, help="the quality to reach")
    who = ap.add_mutually_exclusive_group(required=True)
    who.add_argument("--save", help="the character's .fch file (uses its name and the upgrade seeds stored in it)")
    who.add_argument("--name", help="a character name, for a character that has never used the Forge of Potential")
    ap.add_argument("--max-copies", type=int, default=MAX_COPIES, help=f"give up after this many copies "
                    f"(default: {MAX_COPIES:,})")
    ap.add_argument("-v", "--verbose", action="store_true", help="show how far every copy got")
    ap.add_argument("--json", action="store_true", help="print the result as JSON")
    args = ap.parse_args()
    try:
        prefab = find(args.item)
        if not 1 <= args.target <= oracle.WEB_MAX_QUALITY:
            raise oracle.SaveError(f"the target quality must be between 1 and {oracle.WEB_MAX_QUALITY}")
        if args.save:
            save = oracle.load(args.save)
            name, seeds, source = save["name"], save["seeds"], f"{len(save['seeds'])} saved seeds from the file"
        else:
            name, seeds, source = args.name, {}, "a new character: rolls from the name"
        copies, spent, refunded, done = simulate(prefab, args.target, name, seeds, args.max_copies)
    except FileNotFoundError:
        ap.error(f"file not found: {args.save}")
    except oracle.SaveError as e:
        ap.error(str(e))
    if args.json:
        print(json.dumps({"item": ITEMS[prefab]["name"], "target": args.target, "character": name, "reached": done,
                          "stationCap": ITEMS[prefab]["cap"], "copies": len(copies),
                          "attempts": sum(len(c["steps"]) for c in copies),
                          "spent": dict(spent), "refunded": dict(refunded),
                          "net": {k: spent[k] - refunded[k] for k in spent}}, indent=1))
    else:
        report(prefab, args.target, name, source, copies, spent, refunded, done, args.verbose)


if __name__ == "__main__":
    main()
